BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷85·晋少帝本纪·开运三年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/jiuwudaishi-085-946-october/source.txt", "note": "《旧五代史》卷85·晋少帝本纪·开运三年十月，段落 jiu-wudaishi-205deb4a7860-p002045；已回查卷题、上下文与传主，纸本及异文待核。", "id": "c4bdfca9-7fb5-5280-8404-d97373eb717a"}, {"title": "资治通鉴·卷285·开运三年·十月至十一月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/tongjian-285-946-october-november/source.txt", "note": "《资治通鉴》卷285·开运三年·十月至十一月及追述，段落 zizhi-tongjian-a63549944a71-p003388；已回查卷题、上下文与传主，纸本及异文待核。", "id": "07de3176-9c71-561c-a46f-742fe325de90"}, {"title": "新五代史·卷62·南唐世家·陈诲后续活动校核", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-062-chen-hui-later/source.txt", "note": "《新五代史》卷62·南唐世家·八年陈诲参战，段落 xin-wudaishi-b08f244b9241-p003145；仅作946年死亡记载的时序异说校核，不提前录入后续战事；纸本及异文待核。", "id": "a90839a2-9053-5777-b22f-e70b09603b35"}, {"title": "新五代史·卷67·吴越世家·钱弘佐救福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-067-fuzhou-relief/source.txt", "note": "《新五代史》卷67·吴越世家·钱弘佐救福州，段落 xin-wudaishi-b08f244b9241-p003373；已回查卷题、上下文与传主，纸本及异文待核。", "id": "d49e8d36-e61b-5b0f-a6aa-358fa4c4e901"}, {"title": "资治通鉴·卷285·开运三年·八月至十月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e66af1aafd18c0050199cc2962fef4065cc04d3a/content/books/zizhi-tongjian/vol-285/year-0946/part-03/sources/library/tongjian-285-946-august-october/source.txt", "note": "《资治通鉴》卷285·开运三年·八月至十月及追述，段落 zizhi-tongjian-a63549944a71-p003387；已核正文传主及上下文，底本原字保留，纸本及异文待核。", "id": "28173612-f46c-5aee-bcff-992e0ccab0df"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年九月及赵延寿书信追述", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-zhao-correspondence/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年九月及赵延寿书信追述，段落 jiu-wudaishi-205deb4a7860-p002042；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "c4802c9d-998b-5954-a3e2-b9d3cdf08d38"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "刘延祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：刘延祚。", "biography": null, "status": "draft", "id": "b56b0884-9dcd-50db-b54c-9140684a196c"}, {"name": "王峦", "aliases": ["王巒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王峦，殿直、奉命往卫州者。", "biography": null, "status": "draft", "id": "2fda3de7-baad-51c3-969f-6e43820b6ae3"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "慕容迁", "aliases": ["慕容遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：慕容迁，此前牙将、后控鹤指挥使。", "biography": null, "status": "draft", "id": "23881cae-e844-542f-8d1e-93ba9f4275f7"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "梁汉璋", "aliases": ["梁漢璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州人，后晋陈州防御使。944年二月乙巳与李守贞、皇甫遇、薛怀让等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f62e9bd0-d874-521f-b4ff-27f731b77abb"}, {"name": "宋彦筠", "aliases": ["宋彥筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前同州节度使，滑州人。941年十一月丁丑受任高行周的副将，参与南面军前讨伐安从进的部署。生卒年未载。", "biography": null, "status": "draft", "id": "a66a316a-5777-5c2c-aaa8-0e523f85477d"}, {"name": "王饶", "aliases": ["王饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国左厢都指挥使。946年十月辛未，石重贵任命他为北征军的步军右厢都指挥使。《旧五代史》卷85记有相同部署。生卒年及籍贯未载。", "biography": null, "status": "draft", "id": "0da0dd37-babc-548d-b33d-f587847464ed"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "林赞尧", "aliases": ["林贊堯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐漳州将领。946年十月条下记他作乱，杀监军使周承义及剑州刺史陈诲；泉州刺史留从效起兵将他逐出。陈诲死亡的这条记载与另一史书记载的后续活动有疑问，需进一步核对。林赞尧生卒年未载。", "biography": null, "status": "draft", "id": "c97931a0-9056-5ba4-aef1-89edbc12cb9b"}, {"name": "周承义", "aliases": ["周承義"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "南唐监军使。946年十月条下记漳州将林赞尧作乱时杀死他。原文未说明籍贯、年龄和亲属。", "biography": null, "status": "draft", "id": "4d7a9ad4-8b6a-5299-91ec-057bd5bc7772"}, {"name": "陈诲", "aliases": ["陳誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建安人，王延政麾下战棹都头。940年三月在夜袭中杀死潘师逵。生卒年未载。", "biography": null, "status": "draft", "id": "8c18058e-c4f8-52ab-a4d2-9caaba34336a"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "董思安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年参与反朱文进的谋议和泉州政变，后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "385e66d6-1650-5db4-a215-4208ca968420"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "水丘昭券", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临安人，吴越内都监使。946年福州求救时，他主张出兵。钱弘佐让他掌管用兵，他因忌惮程昭悦而让出此事。原文未载生卒年。", "biography": null, "status": "draft", "id": "f1cf3b01-3f76-5d76-92a7-87fd41eb433c"}, {"name": "张筠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：张筠。", "biography": null, "status": "draft", "id": "bf64af0b-0098-59b2-a778-9ac82b9245d0"}, {"name": "赵承泰", "aliases": ["趙承泰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越统军使。946年十月壬午，钱弘佐派他与张筠率三万兵分水陆救援福州。《新五代史》卷67也记这次派兵。生卒年未载。", "biography": null, "status": "draft", "id": "3ae467d8-e93a-584f-8c92-de2a45c3cb22"}, {"name": "程昭悦", "aliases": ["程昭悅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱塘富人，通过财物结交杜昭达、阚璠，得以接近钱弘佐。后来谋排阚璠，诬告阚璠、杜昭达拥立钱仁俊，使两人遇害、钱仁俊失官被囚，并清除百余权位与自己相当或被自己忌恨的人。生卒年本段未载。", "biography": null, "status": "draft", "id": "4dcc2f3e-2f3d-5dcd-b573-598392035d56"}, {"name": "元德昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "危仔倡之子。946年吴越出兵救福州时，钱弘佐把军事谋划交给他。其姓名与父亲异姓按史书记载保留，不据此猜测改姓原因或收养关系；生卒年未载。", "biography": null, "status": "draft", "id": "3f40b6ff-27d0-5eae-a8f2-983b144f4081"}, {"name": "危仔倡", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“淮南军攻信州，危仔倡向吴越求援”中为求援者。", "biography": null, "status": "draft", "id": "c501d7c0-2e8e-5d14-b46a-6be550f655c5"}, {"name": "钱弘亿", "aliases": ["錢弘億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "11129a7d-ca77-5d63-b3fd-b341fb184b7e"}, {"name": "乐平长公主（杜重威妻）", "aliases": ["乐平长公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的妹妹、杜重威的妻子。937年的记载称她为乐平长公主。", "biography": null, "status": "draft", "id": "7cf58667-5bd6-58c5-8ebe-c3c1d463a473"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
